```ts
function filterWithGuard<T, U extends T>(
  arr: T[],
  predicate: (item: T) => item is U
): U[] {
  const result: U[] = [];
  for (const item of arr) {
    if (predicate(item)) result.push(item);
  }
  return result;
}

// Usage:
export function fetchVerifiedUsers(results: UserRecord[]): UserProfile[] {
  const verified = filterWithGuard(
    results,
    (u): u is Extract<UserRecord, { phoneNumber: string; isPhoneVerified: true }> =>
      u.phoneNumber !== null && u.isPhoneVerified === true
  );

  return verified.map((u) => ({
    id: u.id,
    name: u.name,
    phone: u.phoneNumber,
    city: u.address?.city ?? 'Unknown'
  }));
}
```

The `filterWithGuard` wrapper works on all TS versions ≥3.0 and avoids ES2021-specific semantics. Use this when deploy-to-old-env constraints outweigh the modest readability gain of native `Array.prototype.filter`.

