ds. This preserves the audit trail while maintaining strict types for the transformation.

```typescript
type FullReading = 
  | { type: 'temperature'; timestamp: number; value: number; unit: 'celsius' | 'fahrenheit'; sensor_id: string }
  | { type: 'humidity'; timestamp: number; value: number; sensor_id: string };

type PartialReading = {
  type: 'system';
  timestamp: number;
  sensor_id: string;
  value?: never; // Explicitly forbid value here
};

type SensorPacket = FullReading | PartialReading;

function processSensorData(readings: unknown[]) {
  const packets = readings.filter((r): r is SensorPacket => 
    typeof r === 'object' && r !== null && 'timestamp' in r
  );

  const results: NormalizedReading[] = [];
  const auditLogs: PartialReading[] = [];

  for (const p of packets) {
    if ('value' in p) {
      // TypeScript now knows p is FullReading
      const val = p.type === 'temperature' && p.unit === 'celsius' 
        ? p.value * 1.8 + 32 
        : p.value;

      results.push({ ts: p.timestamp, val, sensorId: p.sensor_id });
    } else {
      // TypeScript now knows p is PartialReading
      auditLogs.push(p);
    }
  }

  return { results, auditLogs };
}
```

By using `value?: never` in the `PartialReading` type and checking `'value' in p`, you create a type-safe fork in the logic. This prevents the calculation logic from attempting to multiply `undefined` (resulting in `NaN`) while allowing the audit logs to collect the heartbeats from legacy hardware.

