// At component level or in a utils file
const getDefaultableValue = <K extends keyof SegmentSettings>(
  field: K,
  settings: SegmentSettings,
  shotDefaults: ShotDefaults | undefined,
  hasOverride: FieldOverrides | undefined
): { isUsingDefault: boolean; displayValue: string } => {
  const localValue = settings[field] as string | undefined;
  const defaultValue = shotDefaults?.[field as keyof ShotDefaults] as string | undefined;

  const isUsingDefault = !localValue && (
    hasOverride 
      ? !hasOverride[field as keyof FieldOverrides] && shotDefaults !== undefined 
      : defaultValue !== undefined
  );

  return {
    isUsingDefault,
    displayValue: isUsingDefault ? (defaultValue ?? '') : (localValue || ''),
  };
};
```

Then usage becomes clean:

```tsx
const { isUsingDefault, displayValue } = getDefaultableValue('negativePrompt', settings, shotDefaults, hasOverride);
