impl actix_web::FromQueryStr for ListUsersQuery {
    fn from_query_str(query: &str) -> actix_web::Result<Self> {
        serde_qs::from_str(query)
            .map_err(|e| actix_web::error::ErrorBadRequest(e.to_string()))
            .and_then(|mut q: Self| {
                // Override defaults from `#[serde(default)]` with our business defaults
                if q.page == 0 { q.page = 1; }
                if q.page_size == 0 { q.page_size = 50; }
                // Enforce upper bound
                if q.page_size > 100 { return Err(actix_web::error::ErrorBadRequest("page_size must be ≤ 100")); }
                Ok(q)
            })
    }
}

